sp_EditarFornecedor	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_EditarFornecedor`(\n\n    p_idFornecedor INT,\n\n    p_NomeFantasia  VARCHAR(120),\n\n    p_RazaoSocial   VARCHAR(120),\n\n    p_CNPJ          VARCHAR(14),\n\n    p_Telefone      VARCHAR(11),\n\n    p_Email         VARCHAR(80)\n\n)\nBEGIN\n\n    UPDATE Fornecedor SET\n\n        NomeFantasia = p_NomeFantasia,\n\n        RazaoSocial  = p_RazaoSocial,\n\n        CNPJ         = p_CNPJ,\n\n        Telefone     = p_Telefone,\n\n        Email        = p_Email\n\n    WHERE idFornecedor = p_idFornecedor;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
